@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@700;800&family=Nunito:wght@700;800;900&display=swap');

: :root { --ink:#263126; --cream:#fff7df; --green:#3e6d45; --yellow:#ffc94a; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; overflow:hidden; font-family:'Nunito',sans-serif; color:var(--ink); background:#4d8b54; }
.game-shell { width:min(1180px,100vw); height:100vh; min-height:640px; margin:auto; position:relative; overflow:hidden; background:linear-gradient(#72b8cb 0 20%,#91c86d 20% 100%); border-inline:8px solid #31533a; }
.topbar { height:88px; padding:12px 32px 10px; display:flex; align-items:center; justify-content:space-between; background:#fff4ce; border-bottom:6px solid #31533a; box-shadow:0 4px 0 rgba(49,83,58,.25); position:relative; z-index:20; }
.brand { display:flex; align-items:center; gap:12px; }
.brand-mark { width:56px;height:56px;border-radius:50%;background:#f3a92f;border:5px solid #31533a;display:grid;place-items:center;box-shadow:inset 0 -7px 0 #d78a25; }
.brand-mark span { width:28px;height:30px;border-radius:50% 50% 45% 45%;background:#8a5b3c;border:3px solid #31533a;position:relative; }
.brand-mark span:before,.brand-mark span:after { content:'';position:absolute;width:5px;height:5px;border-radius:50%;background:#fff;top:7px; }
.brand-mark span:before{left:5px}.brand-mark span:after{right:5px}
.brand p { margin:0;color:#718158;font-size:11px;letter-spacing:2.2px;text-transform:uppercase;font-weight:900; }
.brand h1 { margin:-3px 0 0;font-family:'Baloo 2',sans-serif;font-size:34px;line-height:1;letter-spacing:1px; }
.icon-btn { width:48px;height:48px;border:4px solid #31533a;border-radius:50%;background:#fff8df;box-shadow:0 4px 0 #31533a;cursor:pointer;color:#31533a; }
.icon-btn svg { width:27px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round; }
.icon-btn.muted { opacity:.55; }
.scoreboard { height:82px;display:flex;justify-content:center;align-items:center;gap:24px;position:relative;z-index:15; }
.stat { min-width:145px;height:62px;border:4px solid #31533a;border-radius:16px;background:#fff8df;display:grid;grid-template-columns:58px 1fr;align-items:center;padding:7px 14px;box-shadow:0 5px 0 rgba(49,83,58,.55); }
.stat span { font-size:12px;letter-spacing:1.5px;color:#718158;font-weight:900; }
.stat strong { font-family:'Baloo 2';font-size:38px;text-align:right;line-height:1; }
.timer-stat { min-width:155px;background:#ffc94a;grid-template-columns:54px 60px 1fr; }
.timer-stat strong { text-align:center;font-size:42px; }
.timer-stat small { font-size:10px;letter-spacing:1px; }
.yard { height:calc(100vh - 246px);min-height:394px;position:relative;background:linear-gradient(180deg,#91c86d 0 17%,#73b45c 17% 100%);overflow:hidden; }
.yard:before { content:'';position:absolute;inset:48% 0 0;background:radial-gradient(ellipse at 50% 55%,rgba(255,255,255,.12),transparent 52%),linear-gradient(135deg,rgba(255,255,255,.08) 25%,transparent 25%) 0 0/42px 42px;opacity:.7; }
.fence { position:absolute;left:0;right:0;top:50px;height:74px;border-top:8px solid #6f4d35;border-bottom:8px solid #6f4d35;background:repeating-linear-gradient(90deg,#a77a4b 0 54px,#815936 54px 62px);box-shadow:0 8px 0 rgba(49,83,58,.13);opacity:.58; }
.cloud { position:absolute;width:82px;height:24px;border-radius:30px;background:rgba(255,255,255,.55);top:22px; }
.cloud:before,.cloud:after{content:'';position:absolute;border-radius:50%;background:inherit}.cloud:before{width:38px;height:38px;left:12px;bottom:6px}.cloud:after{width:28px;height:28px;right:12px;bottom:5px}.cloud-one{left:8%}.cloud-two{right:10%;top:34px;transform:scale(.7)}
.board { position:absolute;z-index:5;left:50%;top:52%;width:min(780px,72vw);height:min(390px,72%);transform:translate(-50%,-50%);display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:4px 18px; }
.hole { position:relative;display:flex;align-items:flex-end;justify-content:center;cursor:pointer;user-select:none;-webkit-tap-highlight-color:transparent; }
.hole:after { content:'';position:absolute;z-index:1;bottom:11px;width:78%;height:28%;border-radius:50%;background:#564332;border:7px solid #3d3025;box-shadow:0 8px 0 #4a713f,inset 0 7px 0 #31251e; }
.mole { position:absolute;z-index:3;bottom:19%;width:68%;height:67%;max-height:112px;transform:translateY(70%) scale(.92);transition:transform .12s cubic-bezier(.2,.9,.3,1.3);pointer-events:none; }
.hole.active .mole { transform:translateY(0) scale(1); }
.hole.hit .mole { animation:bonk .18s ease-out; }
@keyframes bonk { 50%{transform:translateY(20%) scale(.85) rotate(8deg)} }
.mole-body { position:absolute;left:50%;bottom:0;transform:translateX(-50%);width:76%;height:87%;border:5px solid #4a3827;border-radius:48% 48% 35% 35%;background:#9a7048;box-shadow:inset 0 -12px 0 #805938; }
.ear { position:absolute;z-index:-1;top:7%;width:25%;height:27%;border:5px solid #4a3827;border-radius:50%;background:#d69a73; }.ear.left{left:2%;}.ear.right{right:2%;}
.face { position:absolute;inset:20% 9% 18%;border-radius:48%;background:#bea078; }
.eye { position:absolute;top:18%;width:12%;height:14%;border-radius:50%;background:#2f2a24; }.eye.left{left:22%}.eye.right{right:22%}
.nose { position:absolute;left:50%;top:38%;transform:translateX(-50%);width:23%;height:18%;border:4px solid #4a3827;border-radius:50%;background:#e4a09a; }
.whisker { position:absolute;top:56%;width:24%;height:3px;background:#4a3827; }.whisker.left{left:-3%;transform:rotate(8deg)}.whisker.right{right:-3%;transform:rotate(-8deg)}
.tooth { position:absolute;bottom:1%;left:50%;transform:translateX(-50%);width:29%;height:27%;border-radius:0 0 6px 6px;background:#fffbe9;border:3px solid #4a3827;border-top:0; }
.pop { position:absolute;z-index:8;left:50%;bottom:48%;transform:translateX(-50%);font-family:'Baloo 2';font-size:27px;color:#fff6b5;text-shadow:0 3px 0 #31533a,2px 0 0 #31533a,-2px 0 0 #31533a;animation:pop .55s ease-out forwards;pointer-events:none; }
@keyframes pop { 0%{opacity:0;transform:translate(-50%,10px) scale(.5)}30%{opacity:1;transform:translate(-50%,0) scale(1.1)}100%{opacity:0;transform:translate(-50%,-52px) scale(.9)} }
.overlay { position:absolute;z-index:30;inset:0;display:grid;place-items:center;background:rgba(61,94,58,.16);backdrop-filter:blur(1.5px);transition:.2s; }
.overlay.hidden { opacity:0;pointer-events:none; }
.start-card { width:min(390px,80vw);min-height:280px;text-align:center;padding:24px 38px 28px;background:#fff7dd;border:6px solid #31533a;border-radius:28px;box-shadow:0 10px 0 rgba(49,83,58,.8),0 18px 30px rgba(49,83,58,.25);transform:rotate(-1deg); }
.mini-mole { width:82px;height:82px;margin:-18px auto 8px;border:5px solid #31533a;border-radius:50%;background:#9a7048;display:grid;place-items:center;font-size:27px;font-weight:900;box-shadow:inset 0 -10px 0 #805938;transform:rotate(2deg); }
.eyebrow { margin:0;color:#b36a36;font-size:12px;letter-spacing:2px;font-weight:900; }
.start-card h2 { margin:5px 0 2px;font-family:'Baloo 2';font-size:36px;line-height:1.05; }
.start-card>p:not(.eyebrow) { margin:4px 0 18px;font-size:15px;color:#718158; }
.start-btn { height:64px;width:100%;border:5px solid #31533a;border-radius:18px;background:#ffc94a;box-shadow:0 7px 0 #31533a;display:flex;align-items:center;justify-content:center;gap:14px;color:#31533a;font-family:'Baloo 2';font-size:20px;font-weight:800;cursor:pointer; }
.start-btn b { width:34px;height:34px;border-radius:50%;background:#31533a;color:#fff4ce;display:grid;place-items:center;font-size:16px; }
.start-btn:active { transform:translateY(5px);box-shadow:0 2px 0 #31533a; }
.final-score { height:72px;margin:12px 0 16px;border:3px dashed #9daf74;border-radius:14px;display:flex;flex-direction:column;justify-content:center;background:#edf2c9; }
.final-score span {font-size:10px;letter-spacing:2px;color:#718158}.final-score strong{font-family:'Baloo 2';font-size:38px;line-height:1}
.end-card { min-height:300px; }
footer { height:76px;padding:12px 32px;display:flex;align-items:center;justify-content:space-between;background:#fff4ce;border-top:6px solid #31533a;position:relative;z-index:20; }
.combo { display:flex;align-items:center;gap:12px;font-size:11px;font-weight:900;letter-spacing:1.5px;color:#718158; }.dots{display:flex;gap:5px}.dots i{width:14px;height:14px;border-radius:50%;background:#b9c1a1;border:2px solid #718158}.dots i.on{background:#ffc94a;border-color:#31533a}
footer p { margin:0;font-size:11px;letter-spacing:1.2px;color:#718158;font-weight:900}.mouse-icon{display:inline-grid;place-items:center;width:24px;height:24px;border:2px solid #718158;border-radius:50%;margin-right:6px}
@media(max-height:720px){.topbar{height:76px}.brand h1{font-size:29px}.brand-mark{width:48px;height:48px}.scoreboard{height:72px}.stat{height:56px}.yard{height:calc(100vh - 212px)}footer{height:64px}.board{height:74%;}.mole{max-height:92px}}
@media(max-width:700px){.game-shell{border-inline:0}.topbar{padding:8px 14px;height:72px}.brand h1{font-size:24px}.brand p{font-size:8px}.brand-mark{width:44px;height:44px}.icon-btn{width:42px;height:42px}.scoreboard{gap:6px;height:68px}.stat{min-width:92px;width:27%;height:54px;grid-template-columns:1fr 1fr;padding:5px 8px}.stat strong{font-size:30px}.timer-stat{min-width:112px;grid-template-columns:38px 45px 1fr}.timer-stat strong{font-size:34px}.stat span{font-size:9px}.yard{height:calc(100vh - 204px)}.board{width:94vw;height:min(390px,78%);gap:2px 2px}.mole{width:78%;height:64%;}.hole:after{width:76%;height:24%;border-width:5px}.start-card{width:82vw;padding-inline:24px}.start-card h2{font-size:31px}footer{height:64px;padding:8px 14px}.dots i{width:11px;height:11px}footer p{font-size:9px}}

const board = document.getElementById('board');
const scoreEl = document.getElementById('score');
const timerEl = document.getElementById('timer');
const bestEl = document.getElementById('best');
const startOverlay = document.getElementById('startOverlay');
const endOverlay = document.getElementById('endOverlay');
const finalScore = document.getElementById('finalScore');
const endTitle = document.getElementById('endTitle');
const comboDots = [...document.querySelectorAll('#comboDots i')];

let score = 0;
let combo = 0;
let time = 30;
let playing = false;
let active = new Set();
let timers = [];
let best = Number(localStorage.getItem('whackBest') || 0);
let muted = false;
bestEl.textContent = String(best).padStart(3,'0');

for (let i=0;i<9;i++) {
  const hole = document.createElement('button');
  hole.className = 'hole';
  hole.setAttribute('aria-label','Mole hole');
  hole.innerHTML = `<div class="mole"><div class="ear left"></div><div class="ear right"></div><div class="mole-body"><div class="face"><i class="eye left"></i><i class="eye right"></i><div class="nose"></div><i class="whisker left"></i><i class="whisker right"></i><div class="tooth"></div></div></div></div>`;
  hole.addEventListener('pointerdown', () => hit(i, hole));
  board.appendChild(hole);
}

function tone(freq, duration=.07) {
  if (muted) return;
  try {
    const ctx = tone.ctx || (tone.ctx = new (window.AudioContext || window.webkitAudioContext)());
    const osc = ctx.createOscillator(); const gain=ctx.createGain();
    osc.type='square'; osc.frequency.value=freq; gain.gain.setValueAtTime(.035,ctx.currentTime); gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);
    osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+duration);
  } catch {}
}

function hit(i, hole) {
  if (!playing || !active.has(i)) return;
  active.delete(i); hole.classList.remove('active'); hole.classList.add('hit');
  setTimeout(()=>hole.classList.remove('hit'),180);
  combo++;
  const points = combo >= 5 ? 20 : 10;
  score += points;
  scoreEl.textContent = String(score).padStart(3,'0');
  const pop=document.createElement('span'); pop.className='pop'; pop.textContent='+'+points; hole.appendChild(pop); setTimeout(()=>pop.remove(),550);
  tone(180+combo*18,.08);
  comboDots.forEach((dot,n)=>dot.classList.toggle('on',n < Math.min(combo,5)));
}

function updateCombo() {
  if (combo>0) { combo=0; comboDots.forEach(d=>d.classList.remove('on')); }
}

function showMole() {
  if (!playing) return;
  const available=[...board.children].map((_,i)=>i).filter(i=>!active.has(i));
  if (!available.length) return;
  const i=available[Math.floor(Math.random()*available.length)];
  const hole=board.children[i]; active.add(i); hole.classList.add('active');
  tone(80,.025);
  const lifetime=Math.max(430,900-time*10-(combo>4?120:0));
  setTimeout(()=>{ if(active.has(i)){ active.delete(i);hole.classList.remove('active');updateCombo(); }},lifetime);
}

function spawnLoop() {
  showMole();
  if (time<20 && Math.random()<.35) setTimeout(showMole,170);
  const next=Math.max(360,720-time*9)+Math.random()*180;
  timers.push(setTimeout(spawnLoop,next));
}

function startGame() {
  timers.forEach(clearTimeout); timers=[];
  score=0; combo=0; time=30; playing=true; active.clear();
  [...board.children].forEach(h=>h.classList.remove('active','hit'));
  scoreEl.textContent='000';timerEl.textContent='30';comboDots.forEach(d=>d.classList.remove('on'));
  startOverlay.classList.add('hidden'); endOverlay.classList.add('hidden');
  tone(260,.05);
  spawnLoop();
  timers.push(setInterval(()=>{
    time--; timerEl.textContent=String(time).padStart(2,'0');
    if(time<=0) endGame();
  },1000));
}

function endGame() {
  if(!playing) return;
  playing=false; timers.forEach(clearTimeout); timers=[]; active.clear();
  [...board.children].forEach(h=>h.classList.remove('active','hit'));
  if(score>best){best=score;localStorage.setItem('whackBest',best);bestEl.textContent=String(best).padStart(3,'0');endTitle.textContent='New high score!';}
  else endTitle.textContent=score>=150?'Mole master!':score>0?'Nice whacking!':'So close!';
  finalScore.textContent=String(score); endOverlay.classList.remove('hidden'); tone(130,.18);
}

document.getElementById('startBtn').addEventListener('click',startGame);
document.getElementById('againBtn').addEventListener('click',startGame);
document.getElementById('soundBtn').addEventListener('click',e=>{muted=!muted;e.currentTarget.classList.toggle('muted',muted);});

